create table if not exists public.memberships(id uuid primary key default gen_random_uuid(),user_id uuid unique references auth.users(id) on delete cascade,status text not null default 'inactive' check(status in('active','inactive','cancelled','past_due')),razorpay_subscription_id text unique,current_period_end timestamptz,created_at timestamptz default now());alter table public.memberships enable row level security;create policy "read own membership" on public.memberships for select to authenticated using(auth.uid()=user_id);